"""
Builds benchmarks/waterfall.bb with blitzcc, runs it and prints the frame times and what the frames cost: a river that falls
over a cliff, made of thousands of see-through sprites. The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/waterfall.py [--sprites N] [--static] [common options, see --help]

--sprites defaults to $BENCH_SPRITES or 5000, --frames to $BENCH_FRAMES or 300; "--sprites 50000" is the heavy run, and
"--quick" is 500 sprites and 30 frames for a look whether it works. -d builds without optimization (which BLITZLLVM_PROFILE_FPS
profiling needs together with --profile); the build configuration is part of the result so runs are not mixed up.
BENCH_DITHER and BENCH_RAW are passed on to the program (see waterfall.bb); --depth 30 or 64 has more than 8 bits per channel in BlitzLLVM.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the
folder with bin\\ in it unless it is set). It has no -O3 and no --profile, and no draw counters (they are 0), and it can have at most 16125 water sprites.

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import os
import benchutil

# Most water sprites the original Blitz3D 1.118 can have (measured by Xaymar: 16125 runs, more crashes). All sprites share one vertex
# buffer of 4 vertices each, Sprite::allocIndex grows it 256 sprites at a time, and Direct3D 7 buffers hold at most 65535 vertices:
# 63 * 256 = 16128 sprites (64512 vertices) fit, the step to 16384 sprites (65536 vertices) fails. waterfall.bb makes 3 hidden
# template sprites, which count too, so 16128 - 3 = 16125 are left for the water.
ORIGINAL_MAX_SPRITES = 16125


def main():
    runner = benchutil.Runner("waterfall", __doc__, frames=300)
    runner.parser.add_argument("--sprites", type=int, default=int(os.environ.get("BENCH_SPRITES", 5000)))
    runner.parser.add_argument("--static", action="store_true", help="the water stays where it starts, only the camera moves")
    args = runner.parse()
    if args.quick:
        args.sprites = 500
    runner.original_limit(args.sprites > ORIGINAL_MAX_SPRITES,
                          "The original Blitz3D can draw only %d water sprites (they share one vertex buffer of 4 vertices each that grows 256 "
                          "sprites at a time, Direct3D 7 buffers have at most 65535 vertices, and 3 more sprites are templates); use --sprites %d or less with it, or BlitzLLVM for more." % (ORIGINAL_MAX_SPRITES, ORIGINAL_MAX_SPRITES))
    v = runner.run({"BENCH_SPRITES": args.sprites, "BENCH_STATIC": 1 if args.static else 0}, "%d sprites" % args.sprites)
    runner.report(["sprites     %12d%s" % (v["sprites"], " (static)" if args.static else "")], update="moving the sprites")
    runner.save(str(args.sprites), ("sprites", "static"))


if __name__ == "__main__":
    main()
